67	    static int[] buildLongestPrefixSuffixTable(String pattern) {
68	        int[] table = new int[pattern.length()];
69	        int prefixLength = 0;
70	        int currentIndex = 1;
71	
72	        while (currentIndex < pattern.length()) {
73	            if (pattern.charAt(currentIndex) == pattern.charAt(prefixLength)) {
74	                table[currentIndex] = ++prefixLength;
75	                currentIndex++;
76	                continue;
77	            }
78	
79	            if (prefixLength > 0) {
80	                prefixLength = table[prefixLength - 1];
81	            } else {
82	                table[currentIndex] = 0;
83	                currentIndex++;
84	            }
85	        }
86	
87	        return table;
88	    }
